// Each scenario is a made-up history for one or more integrations, with the alerts we expect.
const NOW = Date.now();
const MIN = 60000;
const iso = t => new Date(t).toISOString();
const A = { shop_id: 'shop_mossbank', shop_name: 'Mossbank Ceramics' };
const B = { shop_id: 'shop_quillmoor', shop_name: 'Quillmoor Books' };
const C = { shop_id: 'shop_tallowick', shop_name: 'Tallowick Candles' };

// events every gapMin minutes for 7 days, the last one lastAgoMin minutes ago
const rhythm = (shop, gapMin, lastAgoMin) => {
  const out = [];
  for (let t = NOW - lastAgoMin * MIN; t > NOW - 7 * 1440 * MIN; t -= gapMin * MIN) out.push({ shop_id: shop.shop_id, received_at: iso(t) });
  return out;
};
// request log rows spread over the last 55 minutes
const requests = (shop, counts) => {
  const rows = [];
  for (const [outcome, n, reason] of counts) for (let i = 0; i < n; i++) rows.push({ shop_id: shop.shop_id, outcome, reason: reason || '', received_at: iso(NOW - (2 + Math.floor(53 * i / Math.max(1, n))) * MIN) });
  return rows;
};
const SIG = ['rejected_signature', 0, 'signature does not match'];
const rej = (n, what) => [what ? what[0] : SIG[0], n, what ? what[2] : SIG[2]];

const S = [
  { case_id: 'M01', what: 'Three integrations: one normal, one silent, one error spike', integ: [A, B, C],
    events: [...rhythm(A, 5, 2), ...rhythm(B, 5, 240), ...rhythm(C, 5, 2)],
    requests: [...requests(A, [['accepted', 12]]), ...requests(C, [['accepted', 20], rej(6)])],
    expect: ['shop_quillmoor:silence', 'shop_tallowick:error_spike'] },
  { case_id: 'M02', what: 'Busy integration, last event 2 min ago', integ: [A], events: rhythm(A, 5, 2), requests: requests(A, [['accepted', 12]]), expect: [] },
  { case_id: 'M03', what: 'Busy integration silent for 4 hours', integ: [A], events: rhythm(A, 5, 240), expect: ['shop_mossbank:silence'] },
  { case_id: 'M04', what: 'Low-traffic shop (every 2 h), quiet 3 h = normal for it', integ: [A], events: rhythm(A, 120, 180), expect: [] },
  { case_id: 'M05', what: 'Low-traffic shop (every 2 h), quiet 7 h', integ: [A], events: rhythm(A, 120, 420), expect: ['shop_mossbank:silence'] },
  { case_id: 'M06', what: '5-min rhythm, quiet 59 min (limit 60)', integ: [A], events: rhythm(A, 5, 59), expect: [] },
  { case_id: 'M07', what: '5-min rhythm, quiet 61 min (limit 60)', integ: [A], events: rhythm(A, 5, 61), expect: ['shop_mossbank:silence'] },
  { case_id: 'M08', what: 'Error rate exactly 10% (2 of 20) is not above the limit', integ: [A], events: rhythm(A, 5, 2), requests: requests(A, [['accepted', 18], rej(2)]), expect: [] },
  { case_id: 'M09', what: 'Error rate 15% (3 of 20)', integ: [A], events: rhythm(A, 5, 2), requests: requests(A, [['accepted', 17], rej(3)]), expect: ['shop_mossbank:error_spike'] },
  { case_id: 'M10', what: '2 of 3 rejected: too few requests to judge', integ: [A], events: rhythm(A, 5, 2), requests: requests(A, [['accepted', 1], rej(2)]), expect: [] },
  { case_id: 'M11', what: '10 duplicates and 10 accepted: duplicates are not errors', integ: [A], events: rhythm(A, 5, 2), requests: requests(A, [['accepted', 10], ['duplicate', 10]]), expect: [] },
  { case_id: 'M12', what: 'New integration with only 4 events: still learning, no alert', integ: [A], events: rhythm(A, 1440, 4320), expect: [] },
  { case_id: 'M13', what: 'Integration that never sent anything in 7 days', integ: [A], events: [], expect: ['shop_mossbank:silence'] },
  { case_id: 'M14', what: 'Silent, but the same alert is pending review since 2 h', integ: [A], events: rhythm(A, 5, 240),
    alerts: [{ shop_id: 'shop_mossbank', alert_type: 'silence', status: 'pending review', created_at: iso(NOW - 120 * MIN) }], expect: [], expectSkipped: ['shop_mossbank:silence'] },
  { case_id: 'M15', what: 'Silent, earlier alert is 7 h old', integ: [A], events: rhythm(A, 5, 240),
    alerts: [{ shop_id: 'shop_mossbank', alert_type: 'silence', status: 'pending review', created_at: iso(NOW - 420 * MIN) }], expect: ['shop_mossbank:silence'] },
  { case_id: 'M16', what: 'Silent, earlier alert was rejected by the CSM', integ: [A], events: rhythm(A, 5, 240),
    alerts: [{ shop_id: 'shop_mossbank', alert_type: 'silence', status: 'rejected', created_at: iso(NOW - 60 * MIN) }], expect: ['shop_mossbank:silence'] },
  { case_id: 'M17', what: 'Validation errors 50% (10 of 20)', integ: [A], events: rhythm(A, 5, 2),
    requests: requests(A, [['accepted', 10], ['rejected_validation', 10, 'data.total must be a number']]), expect: ['shop_mossbank:error_spike'] },
  { case_id: 'M18', what: 'Silent and error spike at the same time', integ: [A], events: rhythm(A, 5, 240),
    requests: requests(A, [['rejected_signature', 12, 'signature does not match']]), expect: ['shop_mossbank:error_spike', 'shop_mossbank:silence'] }
];

return S.map(s => ({ json: {
  mode: 'test_detect', case_id: s.case_id, what_it_tests: s.what, now: iso(NOW),
  integrations: s.integ, events: s.events, requests: s.requests || [], alerts: s.alerts || [],
  expected_alerts: [...s.expect].sort(), expected_skipped: [...(s.expectSkipped || [])].sort()
} }));

// Hand-written drafts, good and bad, run through the same Check draft code as the live alerts.
const silence = { minutes_silent: 245, hours_silent: 4, events_last_7_days: 1950, last_event_at: '2026-11-09 14:05 UTC', usual_gap_minutes: 5, threshold_minutes: 60 };
const spike = { window_minutes: 60, requests: 26, rejected: 6, error_rate_pct: 23.1, threshold_pct: 10, top_reason: 'rejected_signature: signature does not match', top_reason_count: 6 };
const goodSilence = 'Hi Mossbank Ceramics team,\n\nWe have not received any events from your store since 2026-11-09 14:05 UTC, which is about 4 hours. Your store usually sends events every few minutes, so this looks unusual.\n\nCould you check:\n- Is the webhook still enabled in your store admin?\n- Did the endpoint URL change after a recent update?\n- Does your webhook log show failed deliveries?\n\nPlease reply with what you find and we will confirm on our side once events arrive again.\n\nBest regards,\nCustomer Success';
const goodSpike = 'Hi Mossbank Ceramics team,\n\nIn the last hour, 23.1% of the webhook requests from your store were rejected because the signature did not match.\n\nCould you check:\n- Was the webhook signing secret changed or regenerated on your side?\n- Is a proxy or plugin changing the request before it is sent?\n\nPlease reply with what you find and we will confirm on our side once requests are accepted again.\n\nBest regards,\nCustomer Success';
const base = (id, what, type, facts, body, expected, extra) => ({ json: Object.assign({
  mode: 'test_check', case_id: id, what_it_tests: what, shop_id: 'shop_mossbank', shop_name: 'Mossbank Ceramics',
  alert_type: type, facts, draft_subject: type === 'silence' ? 'No events from your store since 14:05 UTC' : 'Some webhook requests are being rejected',
  draft_body: body, parse_error: '', expected_pass: expected }, extra || {}) });
const realSecret = $vars.IHM_SECRET_MOSSBANK || 'variable-missing';
const before = 'Please reply with what you find';
return [
  base('C01', 'Good silence draft passes', 'silence', silence, goodSilence, true),
  base('C02', 'Good error-spike draft passes', 'error_spike', spike, goodSpike, true),
  base('C03', 'Wrong rate (25% instead of 23.1%)', 'error_spike', spike, goodSpike.replace('23.1%', '25%'), false),
  base('C04', 'Invented number (300 orders)', 'silence', silence, goodSilence.replace('this looks unusual', 'about 300 orders may be missing'), false),
  base('C05', 'Contains the real signing secret', 'error_spike', spike, goodSpike.replace('Could you check:', 'Your secret is ' + realSecret + '. Could you check:'), false),
  base('C06', 'Contains a key-like hex string', 'error_spike', spike, goodSpike.replace('Could you check:', 'Expected value: 9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08. Could you check:'), false),
  base('C07', 'Mentions another client', 'silence', silence, goodSilence.replace('this looks unusual', 'this looks unusual, unlike Quillmoor Books'), false),
  base('C08', 'No number from the facts at all', 'silence', silence, goodSilence.replace('since 2026-11-09 14:05 UTC, which is about 4 hours', 'for a while'), false, { draft_subject: 'No events from your store' }),
  base('C09', 'AI call failed: no draft', 'silence', silence, '', false, { parse_error: 'AI call failed after retries', draft_subject: '' }),
  base('C10', 'Contains a request signature (v1=...)', 'error_spike', spike, goodSpike.replace('Could you check:', 'Last header: v1=4be1f0aa91c2. Could you check:'), false),
  base('C11', 'Promises a fix right away', 'silence', silence, goodSilence.replace(before, 'We will fix this right away. ' + before), false),
  base('C12', 'Asks for a call', 'error_spike', spike, goodSpike.replace(before, 'Could we jump on a short call to go through it? ' + before), false),
  base('C13', 'Offers free work', 'silence', silence, goodSilence.replace(before, 'Our team can reconnect the webhook for you for free. ' + before), false),
  base('C14', '"Feel free to reply" is not an offer of free work', 'silence', silence, goodSilence.replace(before, 'Feel free to reply with what you find'), true)
];

const runId = 'M' + Date.now().toString(36).toUpperCase();
const runAt = new Date().toISOString();
const want = {};
for (const s of $('Build detection scenarios').all()) want[s.json.case_id] = s.json;
const out = [];
for (const r of $('Run detector').all().map(i => i.json)) {
  const w = want[r.case_id];
  const got = r.problems.filter(p => !p.skipped).map(p => p.shop_id + ':' + p.alert_type).sort();
  const skipped = r.problems.filter(p => p.skipped).map(p => p.shop_id + ':' + p.alert_type).sort();
  const falseAlarms = got.filter(g => !w.expected_alerts.includes(g));
  const missed = w.expected_alerts.filter(e => !got.includes(e));
  const passed = !falseAlarms.length && !missed.length && JSON.stringify(skipped) === JSON.stringify(w.expected_skipped);
  out.push({ json: { run_id: runId, run_at: runAt, suite: 'detector', case_id: r.case_id, what_it_tests: w.what_it_tests,
    expected: (w.expected_alerts.join(', ') || 'no alert') + (w.expected_skipped.length ? ' | skipped ' + w.expected_skipped.join(', ') : ''),
    actual: (got.join(', ') || 'no alert') + (skipped.length ? ' | skipped ' + skipped.join(', ') : ''),
    passed, detail: r.results.map(x => x.shop_id + ' ' + x.status + ' (' + x.note + ')').join('; '),
    false_alarms: falseAlarms.length, missed: missed.length } });
}
// Draft checks. For cases that contain a secret or key, the draft must also be removed
// and the notes must not quote any piece of the secret.
const secret = $vars.IHM_SECRET_MOSSBANK || '';
const chunks = [];
for (let i = 0; i + 4 <= secret.length; i++) chunks.push(secret.slice(i, i + 4));
const LEAK_CASES = ['C05', 'C06', 'C10'];
const cases = {};
for (const c of $('Build draft check cases').all()) cases[c.json.case_id] = c.json;
for (const r of $('Run draft checks').all().map(i => i.json)) {
  const c = cases[r.case_id];
  let passed = r.check_passed === c.expected_pass;
  let note = '';
  if (LEAK_CASES.includes(r.case_id)) {
    const removed = String(r.draft_body || '').startsWith('[removed');
    const quoted = chunks.some(ch => String(r.check_notes || '').includes(ch)) || /numbers not in the facts: /.test(r.check_notes || '');
    if (!removed) { passed = false; note += ' draft not removed;'; }
    if (quoted) { passed = false; note += ' notes quote part of the secret;'; }
  }
  out.push({ json: { run_id: runId, run_at: runAt, suite: 'draft_check', case_id: r.case_id, what_it_tests: c.what_it_tests,
    expected: c.expected_pass ? 'pass' : (LEAK_CASES.includes(r.case_id) ? 'blocked, draft removed, nothing quoted' : 'blocked'),
    actual: (r.check_passed ? 'pass' : 'blocked') + (LEAK_CASES.includes(r.case_id) ? (note ? ',' + note : ', draft removed, nothing quoted') : ''),
    passed, detail: (r.check_notes || '').replace(/[A-Za-z0-9]{20,}/g, '[hidden]'),
    false_alarms: (!c.expected_pass && r.check_passed) ? 1 : 0, missed: 0 } });
}
return out;

const rows = $('Compare expected vs actual').all().map(i => i.json);
const by = s => rows.filter(r => r.suite === s);
const sum = (arr, k) => arr.reduce((a, r) => a + (r[k] || 0), 0);
return [{ json: {
  run_id: rows[0] && rows[0].run_id,
  detector: by('detector').filter(r => r.passed).length + ' of ' + by('detector').length,
  draft_check: by('draft_check').filter(r => r.passed).length + ' of ' + by('draft_check').length,
  false_alarms: sum(by('detector'), 'false_alarms'), missed: sum(by('detector'), 'missed'),
  bad_drafts_let_through: sum(by('draft_check'), 'false_alarms'),
  failures: rows.filter(r => !r.passed).map(r => r.case_id + ': expected ' + r.expected + ', got ' + r.actual + ' (' + r.detail + ')')
} }];
